#[derive(Debug, Clone, PartialEq)]
pub enum Target {
    Slide(i32),
    All,
}

impl Target {
    /// The least number of bits a value takes on the wire.
    pub const MIN_BITS: u64 = 8;

    pub fn encode(&self, w: &mut Writer<'_>) {
        match self {
            Self::Slide(v) => {
                w.u32(0);
                let v = *v;
                w.i32(v);
            }
            Self::All => w.u32(1),
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let tag = r.u32()?;
        let value = match tag {
            0 => Self::Slide(r.i32()?),
            1 => Self::All,
            _ => return Err(DecodeError::BadTag { ty: "Target", tag }),
        };
        Ok(value)
    }
}

