/// a copied shape: its XML, the relations it cites (with the bytes of the parts they point at), its text and the
/// identity of the editor it came from (`source_id`: pasting in the same editor shares the parts)
#[derive(Debug, Clone, PartialEq)]
pub struct ShapeClip {
    pub xml: Vec<u16>,
    pub rels: Vec<ClipRel>,
    pub text: Vec<u16>,
    pub source_id: f64,
    pub slide_path: Vec<u16>,
}

impl ShapeClip {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 96;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.utf16(&self.xml);
        w.len(self.rels.len());
        for e0 in self.rels.iter() {
            e0.encode(w);
        }
        w.utf16(&self.text);
        w.f64(self.source_id);
        w.utf16(&self.slide_path);
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let f_xml = r.utf16()?;
        let f_rels = { let n = r.list_of::<ClipRel>(32)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(ClipRel::decode(r)?); } v };
        let f_text = r.utf16()?;
        let f_source_id = r.f64()?;
        let f_slide_path = r.utf16()?;
        Ok(Self { xml: f_xml, rels: f_rels, text: f_text, source_id: f_source_id, slide_path: f_slide_path })
    }
}

